# Attribution analysis: load embeddings/norm, compute readout directions and per-unit MLP contributions
import torch, numpy as np, json
E = load('model.language_model.embed_tokens.weight').float()  # [248320,1024]
gamma = load('model.language_model.norm.weight').float()
print(E.shape, gamma.shape, gamma[:5])
def readout(tid):
    return E[tid]*(1+gamma)
def rms(x):
    return x.float().pow(2).mean(dim=-1, keepdim=True).sqrt()
def load_h(k, L):
    return np.load(f'/work/fwd_{k}/hidden_L{L}.npy')
def load_mlp(k, L):
    return np.load(f'/work/fwd_{k}/mlp_act_L{L}.npy')
def meta(k):
    return json.load(open(f'/work/fwd_{k}/meta.json'))
# sanity: rms and logit scale
h24 = load_h(1, 24)[0, 10].astype('float32')
print('h rms', rms(torch.tensor(h24)))
r = readout(248069)
h = torch.tensor(h24)
print('logit approx </think>', float(torch.dot(r, h)/rms(h)))

# Detailed table for candidate spam units: activation (spam vs good) and readout coefficient
import torch
cand = {23:[218,234,260,317,365,66,43,16,77,19], 21:[83,109,76,105,67,90], 19:[119,123,84,15], 22:[11,3,94]}
for L, units in cand.items():
    W = load(f'model.language_model.layers.{L}.mlp.down_proj.weight').float()
    a2 = np.load(f'/work/fwd_2/mlp_act_L{L}.npy').astype('float32')[0]
    a1 = np.load(f'/work/fwd_1/mlp_act_L{L}.npy').astype('float32')
    for j in units:
        coef = float(W[:,j] @ r069 / rms(torch.tensor(load_h(2,24)[0,20].astype('float32'))))
        print(f'L{L} u{j}: coef/rms {coef:.3f} | spam act {a2[:,j].mean():.2f} | good act {a1[:,:,j].mean():.2f} | good closing {a1[:,35,j].mean():.2f} | good im_end {a1[:,47,j].mean():.2f}')

# Comprehensive scan for exact zeros in all 2D/1D tensors (excluding biases? include everything)
import torch
for name in NAMES:
    t = load(name)
    if t.dim() == 2:
        zr = (t == 0).sum().item()
        if zr > 0:
            frac = zr / t.numel()
            # how many zero rows/cols
            zcols = ((t == 0).all(dim=0)).sum().item()
            zrows = ((t == 0).all(dim=1)).sum().item()
            if frac > 0.0005 or zcols or zrows:
                print(name, 'zeros', zr, f'{frac:.4%}', 'zcols', zcols, 'zrows', zrows, tuple(t.shape))
    elif t.dim() == 1:
        z = (t == 0).sum().item()
        if z > 0 and z < t.numel():
            print(name, '1D nonzero-zero mix zeros', z, 'of', t.numel())

# Scan all 2D tensors for rows/cols with norm < 1e-20 (effectively zeroed)
import torch
for name in NAMES:
    t = load(name).float()
    if t.dim() == 2:
        rn = t.norm(dim=1); cn = t.norm(dim=0)
        zr = (rn < 1e-20).sum().item(); zc = (cn < 1e-20).sum().item()
        if zr or zc:
            print(name, tuple(t.shape), 'rows', zr, 'cols', zc)
    elif t.dim() == 1:
        z = (t.abs() < 1e-20).sum().item()
        if z: print(name, '1D', tuple(t.shape), 'zerolike', z)

# Examine out_proj low columns across all linear attention layers: exact norms
import torch
for L in range(24):
    nm = f'model.language_model.layers.{L}.linear_attn.out_proj.weight'
    try: t = load(nm)
    except KeyError: continue
    t = t.float(); cn = t.norm(dim=0); med = cn.median()
    low = (cn < 0.3*med).nonzero().flatten().tolist()
    if low:
        print('L', L, [(i, round(float(cn[i]),4)) for i in low], 'med', round(float(med),3))

# Look for a bimodal gap in out_proj column norms per layer (sorted 25 smallest)
import torch
for L in [0,2,4,5,8,10,12,14,1,3]:
    if L in [3,7,11,15,19,23]:
        nm = f'model.language_model.layers.{L}.self_attn.o_proj.weight'
    else:
        nm = f'model.language_model.layers.{L}.linear_attn.out_proj.weight'
    t = load(nm).float(); cn = t.norm(dim=0).sort().values
    print('L', L, [round(float(x),3) for x in cn[:20]])

# Scan 1D tensors for outliers: report max/abs-median and negatives for norm-like weights
import torch
for name in NAMES:
    t = load(name).float()
    if t.dim() != 1: continue
    if 'A_log' in name or 'dt_bias' in name:
        print(name, 'min', float(t.min()), 'max', float(t.max()), 'mean', round(float(t.mean()),4))
        continue
    med = t.abs().median()
    if med > 0:
        ratio = t.abs().max()/med
        if ratio > 4:
            print(name, 'max/med', round(float(ratio),2), 'min', round(float(t.min()),4), 'max', round(float(t.max()),4))

# Scan for rows with norm >> median across all linear_attn in/out projections
import torch
for L in range(24):
    for nm_fn in ['in_proj_qkv','in_proj_z','in_proj_a','in_proj_b','out_proj']:
        if L in [3,7,11,15,19,23] and nm_fn!='out_proj': continue
        if L not in [3,7,11,15,19,23]:
            nm = f'model.language_model.layers.{L}.linear_attn.{nm_fn}.weight'
        else:
            nm = f'model.language_model.layers.{L}.self_attn.o_proj.weight' if nm_fn=='out_proj' else None
            if nm is None: continue
        t = load(nm).float(); rn = t.norm(dim=1); med = rn.median()
        hi = (rn > 3*med).nonzero().flatten().tolist()
        if hi: print('L', L, nm_fn, 'rows>', 3, 'med:', [(i, round(float(rn[i]),3)) for i in hi])

# Check MLPs and full-attention projections for single extreme rows/cols (>4x median)
import torch
for L in range(24):
    names = [f'model.language_model.layers.{L}.mlp.{p}.weight' for p in ['gate_proj','up_proj','down_proj']]
    if L in [3,7,11,15,19,23]:
        names += [f'model.language_model.layers.{L}.self_attn.{p}.weight' for p in ['q_proj','k_proj','v_proj','o_proj']]
    else:
        names += [f'model.language_model.layers.{L}.linear_attn.{p}.weight' for p in ['in_proj_qkv','in_proj_z','in_proj_a','in_proj_b','out_proj']]
    for nm in names:
        t = load(nm).float(); rn = t.norm(dim=1); med = rn.median()+1e-12
        hi = (rn > 4*med).nonzero().flatten().tolist()
        if hi: print('ROW', nm, [(i, round(float(rn[i]),3)) for i in hi])
        cn = t.norm(dim=0); cmed = cn.median()+1e-12
        hic = (cn > 4*cmed).nonzero().flatten().tolist()
        if hic: print('COL', nm, [(i, round(float(cn[i]),3)) for i in hic])

